private static void permuteHelper(List<List<Integer>> result, int[] nums, int start, int end) {
    if (start == end) {
        result.add(new ArrayList<>(Arrays.asList(nums)));
        return;
    }
    for (int i = start; i <= end; i++) {
        swap(nums, start, i);
        permuteHelper(result, nums, start + 1, end);
        swap(nums, start, i); // backtrack
    }
}

