private void permuteHelper(int[] nums, int start, ArrayList<List<Integer>> result) {
    if (start == nums.length) {
        // Store the current permutation in the result list
        result.add(new ArrayList<>(Arrays.asList(nums)));
        return;
    }

    for (int i = start; i < nums.length; i++) {
        // Swap the current element with the element at the start index
        swap(nums, start, i);
        // Recursively find all permutations of the remaining elements
        permuteHelper(nums, start + 1, result);
        // backtrack by swapping the elements back to their original positions
        swap(nums, start, i);
    }
}

