public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }

    int maxPossibleLen = 0;
    for (String s : strings) {
        maxPossibleLen = Math.max(maxPossibleLen, s.length());
    }

    // Check if each substring of each string can be found as a substring in all other strings
    for (int len = 1; len <= maxPossibleLen; len++) {
        boolean found = true;
        for (int i = 0; i <= strings.size() - len; i++) {
            String currentStr = strings.get(i);
            if (!isSubstringInAll(currentStr, len)) {
                found = false;
                break;
            }
            if (found && isSubstringInAll(strings.get(strings.size() - 1 - i), len)) {
                return len;
            }
        }
    }
    return 0;
}

