public static int countOilDeposits(char[][] grid) {
        HashSet<String> visited = new HashSet<>();
        int depositCount = 0;

        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[i].length; j++) {
                if (isOil(grid[i][j], i, j, visited)) {
                    depositCount++;
                    markDeposits(grid, i, j, visited);
                }
            }
        }

        return depositCount;
    }

private static boolean isOil(char cell, int row, int col, HashSet<String> visited) {
        // Check if the cell is already visited or not oil
        if (visited.contains(cell + row + col) || cell == '*') return false;

        visited.add(cell + row + col);
        return cell == '@' || isOil(grid[row - 1][col], row - 1, col, visited) || isOil(grid[row + 1][col], row + 1, col, visited) || isOil(grid[row][col - 1], row, col - 1, visited) || isOil(grid[row][col + 1], row, col + 1, visited);
    }

private static void markDeposits(char[][] grid, int row, int col, HashSet<String> visited) {
        grid[row][col] = '1'; // Mark the cell as visited
        // Traverse all 4 directions
        markDeposits(grid, row - 1, col, visited);
        markDeposits(grid, row + 1, col, visited);
        markDeposits(grid, row, col - 1, visited);
        markDeposits(grid, row, col + 1, visited);
    }

