            if (grid[i][j] == '@') {
                int[][] directions = {{0, 1}, {1, 0}, {1, 1}, {0, -1}};
                if (isOilDeposit(grid, i, j, directions)) {
                    count++;
                }
            }
        }
    }
    return count;
}

private static boolean isOilDeposit(char[][] grid, int x, int y, int[][] directions) {
    if (x < 0 || x >= grid.length || y < 0 || y >= grid[x].length || grid[x][y] == '*') {
        return false;
    }

    grid[x][y] = '*'; // Mark the cell as visited

    for (int[] dir : directions) {
        int nx = x + dir[0], ny = y + dir[1];
        if (isOilDeposit(grid, nx, ny, directions)) {
            return true;
        }
    }

    return false;
}

public static int countOilDeposits(char[][] grid) {
    int count = 0;
    int rows = grid.length;
    if (rows == 0) return count;

    int cols = grid[0].length;
    boolean[][] visited = new boolean[rows][cols];

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (grid[i][j] == '*' && !visited[i][j]) {
                dfs(grid, visited, i, j);
                count++;
            }
        }
    }

    return count;
}

private static void dfs(char[][] grid, boolean[][] visited, int i, int j) {
    if (i < 0 || i >= grid.length || j < 0 || j >= grid[0].length || grid[i][j] == '*' || visited[i][j]) return;
    visited[i][j] = true;
    dfs(grid, visited, i - 1, j); // Up
    dfs(grid, visited, i + 1, j); // Down
    dfs(grid, visited, i, j - 1); // Left
    dfs(grid, visited, i, j + 1); // Right
}

