        adjacentNodes.get(node3).add(node4);
    }

    Queue<String> queue = new LinkedList<>();
    queue.add(start[0] + "," + start[1]);
    Set<String> visited = new HashSet<>();
    visited.add(start[0] + "," + start[1]);

    while (!queue.isEmpty()) {
        String current = queue.poll();
        if (current.equals(end[0] + "," + end[1])) {
            return "can be travelled";
        }

        int x = Integer.parseInt(current.charAt(0) + "");
        int y = Integer.parseInt(current.charAt(2) + "");
        for (String neighbor : adjacentNodes.getOrDefault(current, new HashSet<>())) {
            String neighborX = Integer.parseInt(neighbor.charAt(0) + "");
            String neighborY = Integer.parseInt(neighbor.charAt(2) + "");
            if (x == neighborX && y == neighborY) {
                continue;
            }
            if (!visited.contains(neighbor)) {
                visited.add(neighbor);
                queue.add(neighbor);
            }
        }
    }

    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n == 0|| start.length!=2 ||end.length!=2 ) {
        return "invalid input";
    }
    boolean[][] visited = new boolean[n][n];
    return canTravelMazeDFS(n, start, end, paths, visited) == -1 ? "cannot be travelled" : "can be travelled";
}

private static int canTravelMazeDFS(int n, int[] start, int[] end, int[][] paths, boolean[][] visited) {
    if (start[0] < 0 || start[0] >= n || start[1] < 0 || start[1] >= n || end[0] < 0 || end[0] >= n || end[1] < 0 || end[1] >= n) {
        return -1;
    }
    if (start[0] == end[0] && start[1] == end[1]) {
        return -1;
    }
    if (visited[start[0]][start[1]]) {
        return -1;
    }
    visited[start[0]][start[1]] = true;
    int[] startDirection = new int[]{0, 1}; // Right direction
    int[] endDirection = new int[]{0, -1}; // Left direction
    int[] startNextDirection = new int[]{1, 0}; // Down direction
    int[] endNextDirection = new int[]{-1, 0}; // Up direction
    boolean canTravel = false;
    for (int i = 0; i < 2; i++) {
        int[] nextStart = new int[]{start[0] + startDirection[i], start[1] + startDirection[i]};
        int[] nextEnd = new int[]{end[0] + endDirection[i], end[1] + endDirection[i]};
        if (nextStart[0] < 0 || nextStart[0] >= n || nextStart[1] < 0 || nextStart[1] >= n || nextEnd[0] < 0 || nextEnd[0] >= n || nextEnd[1] < 0 || nextEnd[1] >= n) {
            continue;
        }
        if (canTravelMazeDFS(n, nextStart, end, paths, visited) != -1) {
            canTravel = true;
            break;
        }
        if (canTravelMazeDFS(n, nextEnd, end, paths, visited) != -1) {
            canTravel = true;
            break;
        }
    }
    return canTravel ? -1 : 0;
}

public static String appx(String word1, String word2) {
    String result = "";
    int end = Math.min(word1.length(), word2.length());

    for (int i = 0; i < end; i++) {
        if (word1.charAt(i) == word2.charAt(i)) {
            result += word1.charAt(i);
        }
    }

    int gcd = gcd(result.length(), word1.length() + word2.length() - result.length());
    String reducedResult = result + "/" + (word1.length() + word2.length() - result.length()) / gcd;

    return "appx(" + word1 + "," + word2 + ") = " + reducedResult;
}

private static int gcd(int a, int b) {
    while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

public static String appx(String word1, String word2) {
    int commonCount = 0;
    for (int i = 0; i < word1.length(); i++) {
        for (int j = 0; j < word2.length(); j++) {
            if (word1.charAt(i) == word2.charAt(j)) {
                commonCount++;
                break;
            }
        }
    }

    return "appx(" + word1 + ", " + word2 + ") = " + commonCount + "/" + (word1.length() + word2.length());
}

public static String appx(String word1, String word2) {
    // Calculate the total number of characters in both words
    int totalChars = word1.length() + word2.length();

    // Count the number of common characters
    int commonChars = 0;
    for (int i = 0; i < Math.min(word1.length(), word2.length()); i++) {
        if (word1.charAt(i) == word2.charAt(i)) {
            commonChars++;
        }
    }

    // Calculate the approximate value as a reduced fraction
    String reducedFraction = "appx(" + word1 + ", " + word2 + ") = " + commonChars + "/" + totalChars;
    return reducedFraction;
}

public static String appx(String word1, String word2) {
    int commonCount = 0;
    for (int i = 0; i < word1.length() && i < word2.length(); i++) {
        if (word1.charAt(i) == word2.charAt(i)) {
            commonCount++;
        }
    }

    BigInteger numerator = BigInteger.valueOf(commonCount);
    BigInteger denominator = BigInteger.valueOf(word1.length() + word2.length() - commonCount);

    return "appx(" + word1 + ", " + word2 + ") = " + numerator.toString() + "/" + denominator.toString();
}

