public double trimMean(int[] arr) {
    Arrays.sort(arr);
    int n = arr.length;
    int remainingSize = (int) (0.9 * n);
    double sum = 0;
    for (int i = remainingSize; i < n - remainingSize; i++) {
        sum += arr[i];
    }
    return sum / remainingSize;
}

public double trimMean(int[] arr) {
    // Sort the array
    Arrays.sort(arr);

    // Calculate the number of elements to trim
    int elementsToTrim = (int) Math.ceil((arr.length + 0.05) * 0.05);

    // Calculate the index of the first element to keep
    int startIndex = elementsToTrim;

    // Calculate the mean of the remaining elements
    double sum = 0;
    for (int i = startIndex; i < arr.length - elementsToTrim; i++) {
        sum += arr[i];
    }

    return sum / (arr.length - 2 * elementsToTrim);
}

public double trimMean(int[] arr) {
    int n = arr.length;
    Arrays.sort(arr);

    int startIdx = (n / 20) + 1;
    int endIdx = n - (n / 20);

    double sum = 0;
    for (int i = startIdx; i < endIdx; i++) {
        sum += arr[i];
    }

    int size = endIdx - startIdx - 1;
    double mean = sum / size;
    return mean;
}

