public boolean canArrange(int[] arr, int k) {
    int n = arr.length;
    int[] modCount = new int[k];

    for (int num : arr) {
        modCount[num % k]++;
    }

    if (n % 2 != 0 || modCount[0] > 0) {
        return false;
    }

    for (int i = 1; i < k / 2; i++) {
        if (modCount[i] != modCount[k - i]) {
            return false;
        }
    }

    return true;
}

public boolean canArrange(int[] arr, int k) {
    int n = arr.length;
    if (n % 2 == 1) {
        return false;
    }

    Map<Integer, Integer> remainderCount = new HashMap<>();
    for (int number : arr) {
        int remainder = number % k;
        if (remainder == 0) {
            remainderCount.put(0, remainderCount.getOrDefault(0, 0) + 1);
        } else {
            remainderCount.put(k - remainder, remainderCount.getOrDefault(k - remainder, 0) + 1);
        }
    }

    if (remainderCount.containsKey(0)) {
        if (remainderCount.get(0) % 2 != 0) {
            return false;
        } else if (remainderCount.get(0) == 2 && k % 2 != 0) {
            return false;
        }
    }

    for (Map.Entry<Integer, Integer> entry : remainderCount.entrySet()) {
        if (entry.getValue() % 2 != 0) {
            return false;
        }
    }

    return true;
}

public boolean canArrange(int[] arr, int k) {
    int[] count = new int[k];
    for (int num : arr) {
        count[(num % k) % k]++;
    }
    int oddCount = count[0];
    for (int j = 1; j < k; j++) {
        if (count[j] != count[k - j]) {
            return false;
        }
    }
    return oddCount <= 1;
}

public boolean canArrange(int[] arr, int k) {
    int remainderCount = 0;
    for (int num : arr) {
        remainderCount = (remainderCount + num % k) % k;
        if (remainderCount == 0 || remainderCount == k / 2) {
            return false;
        }
    }
    return true;
}

public static boolean canArrange(int[] arr, int k) {
        int[] remainderCounts = new int[k];
        for (int num : arr) {
            remainderCounts[num % k]++;
        }
        boolean evenCount = remainderCounts[0] % 2 == 0;
        if (k % 2 == 0) {
            for (int i = 1; i < k / 2; i++) {
                evenCount &= remainderCounts[i] == remainderCounts[k - i];
            }
        } else {
            evenCount &= remainderCounts[0] == remainderCounts[k / 2];
        }
        return evenCount;
    }

public int minTime(int n, int[][] edges, boolean[] hasApple) {
        if (n <= 1) {
            return 0;
        }

        ArrayList<Integer>[] adj = new ArrayList[n];
        boolean[] visited = new boolean[n];
        for (int i = 0; i < n; i++) {
            adj[i] = new ArrayList<>();
            visited[i] = false;
        }

        for (int[] edge : edges) {
            adj[edge[0]].add(edge[1]);
            adj[edge[1]].add(edge[0]);
        }

        visited[0] = true;
        return dfs(adj, 0, hasApple, visited);
    }

private int dfs(ArrayList<Integer>[] adj, int node, boolean[] hasApple, boolean[] visited) {
        int totalTime = 0;
        for (int neighbor : adj[node]) {
            if (!visited[neighbor]) {
                visited[neighbor] = true;
                totalTime += dfs(adj, neighbor, hasApple, visited);
            }
        }

        if (node == 0 || hasApple[node]) {
            totalTime += 2; // 1 sec to collect and return
        }

        return totalTime;
    }

