private int dfs(int node, int parent, Set<Integer> visited, List<List<Integer>> adj, boolean[] hasApple) {
        visited.add(node);
        int time = 0;
        for (int next : adj.get(node)) {
            if (next != parent) {
                time += dfs(next, node, visited, adj, hasApple);
            }
        }
        if (node == 0 || hasApple[node]) {
            time += 2; // Plus for the return to the root
        }
        return time;
    }

