private void dfs(int node, List<List<Integer>> graph, boolean[] hasApple, int[] time, boolean[] found) {
    if (visited.contains(node)) {
        return;
    }
    visited.add(node);
    time[node] = 0;
    int totalTime = 0;
    for (int neighbor : graph.get(node)) {
        dfs(neighbor, graph, hasApple, time, found);
        totalTime = Math.max(totalTime, time[neighbor] + 1);
        if (totalTime > 0 && (hasApple[neighbor] || found[neighbor])) {
            found[node] = true;
            if (node != 0) {
                time[node] += totalTime;
                total += totalTime;
            }
        }
    }
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Create adjacency list to represent the tree graph
    List<Integer>[] graph = new List[n];
    for (int i = 0; i < n; i++) {
        graph[i] = new ArrayList<>();
    }
    for (int[] edge : edges) {
        graph[edge[0]].add(edge[1]);
        graph[edge[1]].add(edge[0]);
    }

    // Depth-first search function to determine the minimum time to collect apples
    private void dfs(int node, int parent, int time) {
        int total = 0;
        // Check if the current node has an apple
        if (hasApple[node]) {
            total++;
        }

        // Traverse the children of the current node
        for (int child : graph[node]) {
            if (child != parent) {
                dfs(child, node, time + 1);
                total += time + 1;
            }
        }

        // Return the minimum time based on whether children have apples or not
        return total;
    }

    // Start the DFS from node 0 and calculate the minimum time
    return dfs(0, -1, 0);
}

private void dfs(int node, int parent, int time) {
        int total = 0;
        // Check if the current node has an apple
        if (hasApple[node]) {
