        // Traverse the children of the current node
        for (int child : graph[node]) {
            if (child != parent) {
                dfs(child, node, time + 1);
                total += time + 1;
            }
        }

        // Return the minimum time based on whether children have apples or not
        return total;
    }

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    Map<Integer, List<Integer>> adjList = new HashMap<>();
    Set<Integer> visited = new HashSet<>();
    List<Integer> tree = new ArrayList<>();

    // Build the adjacency list representation of the tree
    for (int[] edge : edges) {
        adjList.computeIfAbsent(edge[0], k -> new ArrayList<>()).add(edge[1]);
        adjList.computeIfAbsent(edge[1], k -> new ArrayList<>()).add(edge[0]);
    }

    // Perform a depth-first search to identify all nodes that are reachable from node 0
    stackDFS(0, adjList, tree, visited);

    // Calculate the minimum time required to collect all apples and return to node 0
    int time = 0;
    int level = 0;

    for (int i = tree.size() - 1; i >= 0; i--) {
        if (hasApple[i]) {
            time += level;
            level = 0;
        } else {
