        }
    }

    return time + (hasApple[0] ? level : 0);
}

private void stackDFS(int node, Map<Integer, List<Integer>> adjList, List<Integer> tree, Set<Integer> visited) {
    visited.add(node);
    tree.add(node);
    List<Integer> neighbors = adjList.get(node);

    for (int neighbor : neighbors) {
        if (!visited.contains(neighbor)) {
            stackDFS(neighbor, adjList, tree, visited);
            level++;
            tree.add(node);
        }
    }
}

public String sortString(String s) {
    StringBuilder result = new StringBuilder();
    while (!s.isEmpty()) {
        // Step 1: Find the smallest character not already in the result
        char smallest = 'z' + 1;
        for (char ch : s.toCharArray()) {
            if (ch < smallest && Character.isLetter(ch)) {
                smallest = ch;
            }
        }
        // Step 2: Remove all occurrences of the smallest character
        s = s.replace(smallest, '\0');
        result.append(smallest);
        // Step 3: Find the largest character not already in the result
        char largest = 'a' - 1;
        for (char ch : s.toCharArray()) {
            if (ch > largest && Character.isLetter(ch)) {
                largest = ch;
            }
        }
        // Step 4: Remove all occurrences of the largest character
        s = s.replace(largest, '\0');
        result.append(largest);
    }
    return result.toString();
}

