    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return cost[0];
    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];
    for (int i = 2; i < n; i++) {
        dp[i] = cost[i] + Math.min(dp[i - 1], dp[i - 2]);
    }
    return Math.min(dp[n - 1], dp[n - 2]);
}

private static int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }

    if (cost.length == 1) {
        return cost[0];
    }
    if (cost.length == 2) {
        return Math.min(cost[0], cost[1]);
    }

    int[] dp = new int[cost.length];
    dp[0] = cost[0];
    dp[1] = cost[1];

    for (int i = 2; i < cost.length; i++) {
        dp[i] = Math.min(dp[i - 1], dp[i - 2]) + cost[i];
    }

    return Math.min(dp[dp.length - 1], dp[dp.length - 2]);
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) return 0;
    if (cost.length == 1) return cost[0];

    return Math.min(minCostClimbingStairs(cost, 0), minCostClimbingStairs(cost, 1));
}

private int minCostClimbingStairs(int[] cost, int index) {
    if (index >= cost.length) return 0;
    int twoSteps = minCostClimbingStairs(cost, index + 2) + cost[index];
    int oneStep = minCostClimbingStairs(cost, index + 1) + cost[index];
    return Math.min(twoSteps, oneStep);
}

public int minCostClimbingStairs(int[] cost) {
    if (cost.length == 0) return 0;
    if (cost.length <= 2) return Math.min(cost[0], cost[1]);
    int[] dp = new int[cost.length];
    dp[0] = cost[0];
    dp[1] = cost[1];
    for (int i = 2; i < dp.length; i++) {
        dp[i] = cost[i] + Math.min(dp[i - 1], dp[i - 2]);
    }
    return Math.min(dp[dp.length - 1], dp[dp.length - 2]);
}

