public boolean hasAllCodes(String s, int k) {
    boolean[] indicators = new boolean[1 << k];
    for (int i = 0; i < s.length(); i++) {
        if (i >= k && s.substring(i - k + 1, i + 1).equals("1")) {
            indicators[s.substring(i - k + 1, i + 1)] = true;
        }
    }
    for (boolean b : indicators) {
        if (b == false) return false;
    }
    return true;
}

