        int uniqueCount = (1 << k) - 1;
        int mask = (1 << k) - 1;
        boolean[] bits = new boolean[uniqueCount + 1];

        for (int i = 0; i + k <= n; i++) {
            int binaryNum = Integer.parseInt(s.substring(i, i + k), 2);
            if (!bits[binaryNum]) {
                bits[binaryNum] = true;
                uniqueCount--;
                if (uniqueCount == 0) return true;
            }
        }

        return false;
    }

