    boolean[] seen = new boolean[num];

    for (int i = 0; i <= s.length() - k; i++) {
        String sub = s.substring(i, i + k);
        int index = Integer.parseInt(sub, 2);
        if (index >= num || seen[index]) {
            return false;
        }
        seen[index] = true;
    }

