}

public boolean hasAllCodes(String s, int k) {
    // Use a set to store all possible k-length binary strings
    Set<String> subset = new HashSet<>();
    for (int i = 0; i <= s.length() - k; i++) {
        // Extract a substring of length k from the beginning of the string
        String substring = s.substring(i, i + k);
        // Add the substring to the set
        subset.add(substring);
    }
    // Return true if the size of the set is equal to 2^k, as all k-length binary strings must be present
    return subset.size() == (1 << k);
}

