            maxSum = nums[i];
        }
    }

    return Math.max(totalSum - minSum, totalSum - maxSum);
}

public int maxAbsoluteSum(int[] nums) {
    int negativeSum = nums[0];
    int positiveSum = nums[0];
    int maxSum = nums[0];

    for (int i = 1; i < nums.length; i++) {
        if (nums[i] < 0) {
            if (i == 0 || negativeSum < nums[i])
                negativeSum = nums[i];
            else
                negativeSum += nums[i];
        }
        else {
            if (i == 0 || positiveSum > nums[i])
                positiveSum = nums[i];
            else
                positiveSum += nums[i];
        }

        maxSum = Math.max(maxSum, Math.max(negativeSum, positiveSum));
    }

    return maxSum;
}

public int maxAbsoluteSum(int[] nums) {
    int maxSum = Integer.MIN_VALUE;
    int minSum = Integer.MAX_VALUE;
    int currentMaxSum = 0;
    int currentMinSum = 0;

    for(int num : nums) {
        currentMaxSum = Math.max(num, currentMaxSum + num);
        currentMinSum = Math.min(num, currentMinSum + num);

        maxSum = Math.max(maxSum, currentMaxSum);
        minSum = Math.min(minSum, currentMinSum);
    }

    return Math.max(maxSum, -minSum);
}

public int maxAbsoluteSum(int[] nums) {
