    for(int num : nums) {
        maxSum = Math.max(num, maxSum + num);
        minSum = Math.min(num, minSum + num);
        res = Math.max(res, Math.abs(maxSum));
        res = Math.max(res, Math.abs(minSum));
    }
    return res;
}

public int findMinFibonacciNumbers(int k) {
    ArrayList<Integer> fib = new ArrayList<>();
    fib.add(1);
    fib.add(1);
    while (fib.get(fib.size() - 1) <= k) {
        fib.add(fib.get(fib.size() - 1) + fib.get(fib.size() - 2));
    }

    int count = 0;
    while (k > 0) {
        int index = fib.size() - 1;
        while (index >= 0 && fib.get(index) > k) {
            index--;
        }
        if (index >= 0) {
            k -= fib.get(index);
            count++;
        }
    }

    return count;
}

public int findMinFibonacciNumbers(int k) {
