    while (fibSequence.get(fibSequence.size() - 1) < k) {
        fibSequence.add(fibSequence.get(fibSequence.size() - 1) + fibSequence.get(fibSequence.size() - 2));
    }
    return findMinFibonacciNumbersRec(k, fibSequence.toArray(new Integer[]{}));
}

private int findMinFibonacciNumbersRec(int k, Integer[] fibArray) {
    if (k == 0) {
        return 0;
    }
    int[] result = new int[fibArray.length + 1];
    for (int i = 0; i < fibArray.length; i++) {
        if (k >= fibArray[i]) {
            result[k] = Math.min(result[k], 1 + findMinFibonacciNumbersRec(k - fibArray[i], fibArray));
        }
    }
    return result[k];
}

public int findMinFibonacciNumbers(int k) {
    int count = 0;
    while (k != 0) {
        if (isFibonacci(k)) {
            k -= k;
            count++;
        } else {
            int closestFib = findClosestFib(k);
            k -= closestFib;
            count++;
        }
    }
    return count;
}

private boolean isFibonacci(int num) {
    return num == 0 || num == 1 || (num > 0 && (num * num + 4) % 8 == 0);
}

private int findClosestFib(int num) {
    int fib1 = 1, fib2 = 1;
    while (fib1 <= num) {
        int nextFib = fib1 + fib2;
        if (nextFib > num) break;
        fib1 = fib2;
        fib2 = nextFib;
    }
    return fib1;
}

