        a = b;
        b = c;
    }

    int result = 0;
    int index = fib.size() - 1;

    while (k > 0) {
        while (fib.get(index) > k) {
            index--;
        }
        if (index < 0) {
            break;
        }
        k -= fib.get(index);
        result++;
    }

    return result;
}

