int maxUniqueSplit(String s) {
    int[] occurrences = new int[100]; // assuming the number of lowercase letters is less than 100
    int maxUnique = 0;
    Set<Character> existingSubstrings = new HashSet<>();
    for (int i = 0; i < s.length(); i++) {
        occurrences[(s.charAt(i) - 'a')]++; // increment the count for the current letter

        while (Occurrences[(s.charAt(i) - 'a')] > 1) { // if the current character appears more than once
            existingSubstrings.remove(s.charAt(i)); // remove the character from the set
            occurrences[(s.charAt(i) - 'a')]--; // decrement the count for the removed character
            i--; // move back one step
        }

        maxUnique = Math.max(maxUnique, existingSubstrings.size()); // update the maximum unique substring count
        existingSubstrings.add(s.charAt(i)); // add the current character to the set
    }
    return maxUnique + 1; // adding one extra for the entire string
}

public int maxUniqueSplit(String s) {
    return dfs(0, new boolean[s.length()], new HashSet<>(), s);
}

private int dfs(int start, boolean[] used, Set<String> uniqueSubstrings, String s) {
    if (start == s.length()) {
        return uniqueSubstrings.size();
    }

    int maxUnique = 0;
    for (int end = start; end < s.length(); end++) {
        if (!used[end]) {
            used[end] = true;
            uniqueSubstrings.add(s.substring(start, end + 1));
            maxUnique = Math.max(maxUnique, dfs(end + 1, used, uniqueSubstrings, s));
            used[end] = false;
            uniqueSubstrings.remove(s.substring(start, end + 1));
        }
    }

    return maxUnique;
}

public int maxUniqueSplit(String s) {
    if (s == null || s.length() == 0) {
        return 0;
    }

    int count = 1;
    TreeSet<String> set = new TreeSet<>();
    set.add(s.substring(0, 1));

    for (int i = 1; i < s.length(); i++) {
        String current = s.substring(0, i + 1);
        if (!set.contains(current)) {
            count++;
            set.add(current);
        } else {
            int prevStart = set.floor(current).length();
            set.clear();
            set.add(s.substring(0, prevStart + 1));
            set.add(current);
        }
    }

    return count;
}

public int maxUniqueSplit(String s) {
