    }

    StringBuilder result = new StringBuilder();
    for (int i = 0; i < n; i++) {
        // Determine the current character
        char currentChar = (char) (i + 'a');
        // Check if adding the current character would not violate the value constraint
        if (k - (i + 1) * (i + 2) >= 0) {
            k -= (i + 1) * (i + 2);
            result.append(currentChar);
        } else {
            // If adding the current character would violate the value constraint, use the previous character
            result.append(result.charAt(result.length() - 1));
        }
    }

    return result.toString();
}

