    // Add 'a' characters to the result
    while (i < n && k >= 1) {
        result.append('a');
        k--;
    }

    // Add 'z' characters if the remaining value k is less than 26
    if (k < 26 && n > 1) {
        result.append((char) (90 - k + 1));
        n--;
    }

