        if (low == 1) {
            result.add(1);
        } else if (low < 10) {
            result.add(0);
            for (int i = 1; i <= 9; i++) {
                if ((i + 1) <= high) {
                    result.add(i + 1);
                }
                if ((i - 1) >= low) {
                    result.add(i - 1);
                }
            }
        }

        for (int i = 10; i <= high; i++) {
            if (checkSteppingNumber(i)) {
                result.add(i);
