public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> steppingNumbers = new ArrayList<>();
    List<Integer> proposedNumbers = new ArrayList<>();
    Queue<Integer> q = new LinkedList<>();
    q.offer(0);

    while (!q.isEmpty()) {
        int current = q.poll();
        if (current >= low && current <= high) {
            steppingNumbers.add(current);
        }
        proposedNumbers.clear();
        proposedNumbers.add(current);

        int lastDigit = current % 10;
        if (lastDigit > 0) {
            proposedNumbers.add(current * 10 + lastDigit - 1);
        }
        if (lastDigit < 9) {
            proposedNumbers.add(current * 10 + lastDigit + 1);
        }

        for (int num : proposedNumbers) {
            if (num >= low && num <= high) {
                q.offer(num);
            }
        }
    }

    Collections.sort(steppingNumbers);
    return steppingNumbers;
}

public static int countDigitOne(int n) {
    int ifOdd = n % 10;
    int ifEven = n / 10;
    int ifOneSpecial = ifOdd == 0 ? ifEven : ifOdd != 1 ? 1 + ifEven * 10 : ifEven * 10;
    return ifEven * (n / 10) + 1 + ifOneSpecial;
}

public static int countDigitOne(int n) {
    if (n <= 0) {
        return 0;
    }
    int count = 0;
    int i = 1;
    while (i <= n) {
        int x = i;
        while (x > 0) {
            count += x % 10 == 1 ? 1 : 0;
            x /= 10;
        }
        i *= 10;
    }
    return count;
}

public static int countDigitOne(int n) {
    int count = 0;
    int power = 1; // Represents the current power of 10
    int index = 10; // Represents the current index in the current power

    while (index <= n) {
        int buf = n / index;
        count += (buf + 8) / 10 * power;
        if (buf % 10 == 1) {
            count += n % index + 1;
        }
        power *= 10;
        index *= 10;
    }

    return count;
}

