public static boolean isPowerOfTwo(int n) {
    // If n is less than or equal to 0, it cannot be a power of two
    if (n <= 0) {
        return false;
    }
    // If n is 1, it is a power of two
    if (n == 1) {
        return true;
    }
    // If n is even but not 2, it is not a power of two
    if (n % 2 != 0) {
        return false;
    }
    // Recursive call to check if n/2 is a power of two
    return isPowerOfTwo(n / 2);
}

