public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) return 0;
    int rows = mat.length;
    int cols = mat[0].length;
    int[][] dp = new int[3][cols]; // dp[0] - horizontal, dp[1] - vertical, dp[2] - diagonal, dp[3] - anti-diagonal

    int max = 0;
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (mat[i][j] == 1) {
                dp[0][j] = (j > 0) ? dp[0][j - 1] + 1 : 1;
                dp[1][j] = (i > 0) ? dp[1][j - 1] + 1 : 1;
                dp[2][j] = (i > 0 && j > 0) ? dp[2][j - 1] + 1 : 1;
                dp[3][j] = (i > 0 && j < cols - 1) ? dp[3][j + 1] + 1 : 1;
                max = Math.max(max, Arrays.stream(dp).max().getAsInt());
            }
        }
    }
    return max;
}

