public static int squarePermutations(int[] A) {
    if (A == null || A.length < 2) {
        return 0;
    }

    // Function to check if a number is a perfect square
    boolean isPerfectSquare(long n) {
        return Math.sqrt(n) == Math.floor(Math.sqrt(n));
    }

    // Function to check if a subarray is a permutation of squares
    boolean isPermutationOfSquares(int[] subArray) {
        long[] squares = new long[subArray.length];
        for (int i = 0; i < subArray.length; i++) {
            squares[i] = (long) subArray[i] * subArray[i];
        }

        Arrays.sort(squares);
        for (int i = 1; i < squares.length; i++) {
            if (!squares[i] == squares[i - 1] + 1) {
                return false;
            }
        }
        return true;
    }

    // Initialize a memoization array to store resultados
    int[] memo = new int[A.length];
    Arrays.fill(memo, -1); // Fill with -1 to mark uncomputed elements

    return countPermutationsWithMemo(A, memo, A.length - 1);
}

