private int countPermutations(int index) {
        if (index == A.length - 1) {
            return (A[index] == A[0] || A[index] % A[index - 1] == 0) ? 1 : 0;
        }

        int count = 0;
        for (int i = index; i < A.length; i++) {
            if (visited.containsKey(i)) continue;
            if ((i > 0 && A[i] == A[i - 1]) || (index > 0 && A[index] - A[i] % A[index - 1] != 0)) continue;

            visited.put(i, 1);
            if (A[i] == A[0] || A[i] % A[index - 1] == 0) {
                count += countPermutations(index + 1);
            }
            visited.remove(i);
        }

        return count;
    }

public static int squarePermutations(int[] A) {
    List<List<Integer>> permutations = new LinkedList<>();
    backtrack(A, 0, permutations);
    return permutations.size();
}

private static void backtrack(int[] A, int start, List<List<Integer>> permutations) {
    if (start == A.length) {
        List<Integer> permutation = new LinkedList<>();
        for (int num : A) {
            permutation.add(num);
        }
        permutations.add(permutation);
        return;
    }

    for (int i = start; i < A.length; i++) {
        if (isInvalidState(A, start, i)) {
            continue;
        }
        swap(A, start, i);
        backtrack(A, start + 1, permutations);
        swap(A, start, i);
    }
}

private static boolean isInvalidState(int[] A, int start, int i) {
    int sum = A[start] + A[i];
    return !isPerfectSquare(sum);
}

private static boolean isPerfectSquare(int num) {
    int sqrt = (int) Math.sqrt(num);
    return sqrt * sqrt == num;
}

public static int squarePermutations(int[] A) {
    int N = A.length;
    int answer = 0;

    // Sort the array to ensure adjacent elements are ordered
    Arrays.sort(A);

    do {
        // Check if the current array is a square permutation
        boolean isSquarePermutation = true;
        for (int i = 1; i < N; i++) {
            if (!isSquare(A[i] + A[i - 1])) {
                isSquarePermutation = false;
                break;
            }
        }

        // If it is a square permutation, increment the count
        if (isSquarePermutation) {
            answer++;
        }
    } while (permute(A));

    return answer;
}

public static boolean isSquare(int x) {
    int sqrt = (int)Math.sqrt(x);
    return sqrt * sqrt == x;
}

public static boolean permute(int[] A) {
    int N = A.length;
    for (int i = N - 1; i >= 2; i--) {
        if (A[i] > A[i - 1]) { // Find the largest element less than the second last element
            for (int j = i - 2; j >= 0; j--) {
                if (A[j] <= A[i - 1] && A[j] > A[i]) { // Find the second largest element greater than A[i-1].1
                    swap(A, i - 1, j);
                    Arrays.sort(A, j, i); // Sort the third to i-1 elements
                    return true;
                }
            }
        }
    }
    return false;
}

public static void swap(int[] A, int i, int j) {
    int temp = A[i];
    A[i] = A[j];
    A[j] = temp;
}

public static int squarePermutations(int[] A) {
    int N = A.length;
    int count = 0;

    for (int i = 0; i < N; i++) {
        for (int j = i + 1; j < N; j++) {
            int sum = A[i] + A[j];
            int sqrt = (int) Math.sqrt(sum);
            if (sqrt * sqrt == sum) {
                swapValues(A, i, j);
                count++;
            }
        }
    }

    return count;
}

private static void swapValues(int[] A, int i, int j) {
    int temp = A[i];
    A[i] = A[j];
    A[j] = temp;
}

public static int largestRectangleArea(int[] heights) {
    int ans = 0;
    Stack<Integer> stack = new Stack<>();
    for(int i = 0; i < heights.length ; i++){
        while(!stack.isEmpty() && heights[i] <= heights[stack.peek()]){
            int h = heights[stack.pop()];
            int width = stack.isEmpty()?i:i-stack.peek()-1;
            ans = Math.max(ans,h*width);
        }
        stack.push(i);
    }
    while(!stack.isEmpty()){
        int h = heights[stack.pop()];
        int width = stack.isEmpty()?heights.length:i-stack.peek()-1;
        ans = Math.max(ans,h*width);
    }
    return ans;
}

public static int largestRectangleArea(int[] heights) {
    int maxArea = 0;
    int left = 0, right = heights.length - 1;
    while (left <= right) {
        int minHeight = Math.min(heights[left], heights[right]);
        int width = right - left + 1;
        maxArea = Math.max(maxArea, minHeight * width);

        if (heights[left] <= heights[right]) {
            left++;
        } else {
            right--;
        }
    }
    return maxArea;
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }

    int n = heights.length;
    int[] stack = new int[n];
    int[] leftSmaller = new int[n];
    int[] rightSmaller = new int[n];
    Arrays.fill(leftSmaller, -1);
    Arrays.fill(rightSmaller, n);

    // Find index of the smallest element to the left of each element
    for (int i = 0; i < n; i++) {
        while (!stack.isEmpty() && heights[stack[stack.length - 1]] >= heights[i]) {
            stack.pop();
        }
        if (!stack.isEmpty()) {
            leftSmaller[i] = stack[stack.length - 1];
        }
        stack.push(i);
    }

    // Clear the stack for next computations
    stack = new int[n];
    Arrays.fill(rightSmaller, -1);
    Arrays.fill(leftSmaller, n);

    // Find index of the smallest element to the right of each element
    for (int i = n - 1; i >= 0; i--) {
        while (!stack.isEmpty() && heights[stack[stack.length - 1]] >= heights[i]) {
            stack.pop();
        }
        if (!stack.isEmpty()) {
            rightSmaller[i] = stack[stack.length - 1];
        }
        stack.push(i);
    }

    int maxArea = 0;

    // Calculate the area of each rectangle and find the maximum
    for (int i = 0; i < n; i++) {
        int width = rightSmaller[i] - leftSmaller[i] - 1;
        int area = width * heights[i];
        maxArea = Math.max(maxArea, area);
    }

    return maxArea;
}

public static int largestRectangleArea(int[] heights) {
