    for (int i = 0; i < n; i++) {
        while (!s.isEmpty() && heights[s.peek()] >= heights[i]) {
            s.pop();
        }
        leftSmaller[i] = s.isEmpty() ? -1 : s.peek();
        s.push(i);
    }

    for (int i = n - 1; i >= 0; i--) {
        while (!s.isEmpty() && heights[s.peek()] >= heights[i]) {
            s.pop();
        }
        rightSmaller[i] = s.isEmpty() ? n : s.peek();
        s.push(i);
    }

    int maxArea = 0;
    for (int i = 0; i < n; i++) {
        maxArea = Math.max(maxArea, (rightSmaller[i] - leftSmaller[i] - 1) * heights[i]);
    }

