public static int[] diagonalOrder(int[][] mat) {
    int rows = mat.length;
    int cols = mat[0].length;
    int[] result = new int[rows * cols];
    int row = 0, col = 0, dir = 1; // Directions: right-down, down-right, left-down, up-left

    for (int i = 0; i < rows * cols; i++) {
        result[i] = mat[row][col];
        // Move to the next position
        if (dir == 1) {
            if (col == cols - 1) {
                row++;
                dir = 2;
            } else if (row == 0) {
                col++;
                dir = 3;
            } else {
                row--;
                col++;
            }
        } else if (dir == 2) {
            if (row == rows - 1) {
                col++;
                dir = 1;
            } else if (col == 0) {
                row++;
                dir = 4;
            } else {
                row++;
                col--;
            }
        } else if (dir == 3) {
            if (col == cols - 1) {
                row--;
                dir = 2;
            } else if (row == 0) {
                col++;
                dir = 4;
            } else {
                row--;
                col++;
            }
        } else if (dir == 4) {
            if (row == 0) {
                col++;
                dir = 1;
            } else if (col == 0) {
                row++;
                dir = 2;
            } else {
                row--;
                col--;
            }
        }
    }

    return result;
}

public static int[] diagonalOrder(int[][] mat) {
    int rows = mat.length;
    int cols = mat[0].length;
    int[] output = new int[rows * cols];
    int index = 0;
    int i = 0;
    int j = 0;

    while (index < rows * cols) {
        output[index++] = mat[i][j];
        if (i == 0 && j != cols - 1) {
            j++;
        } else if (j == cols - 1 && i != rows - 1) {
            i++;
        } else if (i == rows - 1 && j == cols - 1) {
            i--;
            j--;
        } else if (i > 0 && j > 0) {
            i--;
            j++;
        }
    }

    return output;
}

