public static int[] diagonalOrder(int[][] mat) {
    int n = mat.length;
    int m = mat[0].length;
    int[] result = new int[n * m];
    int index = 0;

    for (intdiag = 0; diag < n + m - 1; diag++) {
        if (diag < n) {
            // Top side of the diag is filled in from left
            int end = Math.min(diag, m - 1);
            for (int i = diag; i >= 0 && end >= 0; i--) {
                result[index++] = mat[i][end];
                end--;
            }
        } else {
            // Bottom side of the diag is filled in from right
            int start = Math.min(diag - n + 1, n);
            for (int i = start; i < n && diag - start < m; i++) {
                result[index++] = mat[i][diag - start];
            }
        }
    }

    return result;
}

public static int[] diagonalOrder(int[][] mat) {
    int rows = mat.length;
    int cols = mat[0].length;
    int[] result = new int[rows * cols];
    int top = 0;
    int bottom = rows - 1;
    int left = 0;
    int right = cols - 1;
    int index = 0;

    while (top <= bottom && left <= right) {
        // Traverse left to right
        for (int idx = left; idx <= right; idx++) {
            result[index++] = mat[top][idx];
        }
        top++;

        // Traverse top to bottom
        for (int idx = top; idx <= bottom; idx++) {
            result[index++] = mat[idx][right];
        }
        right--;

        // Check if there are more elements left
        if (top <= bottom) {
            // Traverse right to left
            for (int idx = right; idx >= left; idx--) {
                result[index++] = mat[bottom][idx];
            }
            bottom--;
        }

        // Check if there are more elements to the top
        if (left <= right) {
            // Traverse bottom to top
            for (int idx = bottom; idx >= top; idx--) {
                result[index++] = mat[idx][left];
            }
            left++;
        }
    }

    return result;
}

