private static String buildCenterPattern(int length) {
        StringBuilder pattern = new StringBuilder("0");
        for (int i = 1; i < length; i++) {
            pattern.append(createEdge(i, length - 1));
            pattern.append(createEdge(i - 1, length - 1));
        }
        pattern.append("0");
        return pattern.toString();
    }

private static String createEdge(int middlePosition, int length) {
        int leftIndex = Math.max(0, middlePosition - length / 2 + 1);
        int rightIndex = Math.min(length - 1, middlePosition + length / 2 - 1);
        StringBuilder edge = new StringBuilder();
        for (int i = leftIndex; i <= rightIndex; i++) {
            edge.append((i + Math.max(0, middlePosition - length / 2)) % 2 == 0);
        }
        return edge.toString();
    }

