        for (int j = 1; j * j <= i; j++) {
            min = Math.min(min, 1 + dp[i - j * j]);
        }
        dp[i] = min;
    }

    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    int[] dp = new int[n + 1];
    Arrays.fill(dp, n + 1);

    dp[0] = 0; // Base case: no numbers needed to make sum 0

    for (int i = 1; i <= n; i++) {
        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }

    return dp[n];
}

