public static int minPerfectSquareSum(int n) {
    if (n <= 3) {
        return n;
    }

    int[] dp = new int[n + 1];
    Arrays.fill(dp, Integer.MAX_VALUE);

    dp[0] = 0;

    for (int i = 1; i <= n; i++) {
        for (int j = 1; j * j <= i; j++) {
            int cost = 1 + dp[i - j * j];
            if (cost < dp[i]) {
                dp[i] = cost;
            }
        }
    }

    return dp[n];
}

