public static String reverseWords(String s) {
    StringBuilder reversedSentence = new StringBuilder();
    StringBuilder currentWord = new StringBuilder();

    for (char c : s.toCharArray()) {
        if (c == ' ') {
            // Reverse the current word and append it to the reversed sentence
            reversedSentence.append(currentWord.reverse()).append(" ");
            currentWord.setLength(0); //清空当前单词
        } else {
            currentWord.append(c); // Append character to the current word
        }
    }

    // Append the last word after the loop if it's not followed by a space
    if (!currentWord.isEmpty()) {
        reversedSentence.append(currentWord.reverse());
    }

    // Trim the last space if present
    return reversedSentence.toString().trim();
}
